steps.script:
var l = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/MovementScrollContainer/MovementPanel/Section1_UnitList/MovementUnitList")
if l == null:
	return false
var texts = []
for i in range(l.item_count):
	texts.append(str(l.get_item_text(i)))
return l.item_count > 0 and "|".join(texts).contains("Battlewagon")

var pr = tree.root.get_node("/root/PadRouter")
var mc = tree.current_scene.movement_controller
var models = GameState.get_unit("U_GRETCHIN_T").get("models", [])
var alive = 0
for m in models:
	if m.get("alive", true):
		alive += 1
return alive > 1 and pr.group_carry_active and mc.selected_models.size() == alive

var md = PhaseManager.current_phase_instance.get_active_move_data("U_GRETCHIN_T")
var staged := {}
for sm in md.get("staged_moves", []):
	staged[str(sm.get("model_id", ""))] = true
var models = GameState.get_unit("U_GRETCHIN_T").get("models", [])
var alive = 0
for m in models:
	if m.get("alive", true):
		alive += 1
return alive > 1 and staged.size() == alive
